[package]
name = "terminal_size"
version = "0.4.3"
edition = "2021"
description = "Minimal terminal size detection (local replacement used for help wrapping)"
license = "MIT OR Apache-2.0"

[dependencies]
libc = "0.2"
EOF
cat > src/lib.rs <<'EOF'
//! Minimal terminal-size detection used for wrapping help output.
//!
//! Tries stdout first, then stderr, then stdin, and reports the size of the
//! first stream that is attached to a terminal.

/// Terminal width in columns.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);

/// Terminal height in rows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[cfg(unix)]
fn size_of_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    // SAFETY: TIOCGWINSZ fills a plain-old-data struct; a zeroed value is valid.
    let mut ws: libc::winsize = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws as *mut libc::winsize) };
    if rc != 0 {
        return None;
    }
    if ws.ws_col == 0 || ws.ws_row == 0 {
        return None;
    }
    Some((Width(ws.ws_col), Height(ws.ws_row)))
}

/// Returns the size of the terminal, if any of the standard streams is one.
pub fn terminal_size() -> Option<(Width, Height)> {
    #[cfg(unix)]
    {
        for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
            if let Some(size) = size_of_fd(fd) {
                return Some(size);
            }
        }
        None
    }
    #[cfg(not(unix))]
    {
        None
    }
}
EOF
echo ok"}

