import re
def parse_long(path, width):
    lines = open(path).read().split('\n')
    # options start after "Options:" line; each option header line starts with two spaces and '-' 
    entries = []  # (header, [text lines])
    cur = None
    section = None
    for ln in lines:
        if ln in ('Arguments:', 'Options:'):
            section = ln; continue
        if section is None: continue
        if ln.startswith('  ') and not ln.startswith('          ') and ln.strip():
            cur = [ln.strip(), []]
            entries.append(cur)
        elif cur is not None:
            if ln.startswith('          '):
                cur[1].append(ln[10:])
            elif ln == '':
                cur[1].append(None)  # blank separator between entries (or inside)
    return entries

def reconstruct(textlines, avail):
    # textlines: list of str or None (None = blank line between entries). Inside an entry, blank lines are '' (clap writes indent).
    # strip trailing None
    while textlines and textlines[-1] is None: textlines.pop()
    out = []
    i = 0
    paras = []
    buf = None
    for t in textlines:
        if t is None: t = ''
        if buf is None:
            buf = t
            continue
        if t == '' or buf == '':
            paras.append(buf); buf = t; continue
        first_word = t.split(' ')[0] if t.strip() else ''
        # was the previous line full? i.e. would first word have fit?
        if len(buf.rstrip()) + 1 + len(first_word) <= avail and not t.startswith(' '):
            # explicit newline
            paras.append(buf); buf = t
        elif t.startswith(' '):
            paras.append(buf); buf = t
        else:
            buf = buf + ' ' + t
    if buf is not None: paras.append(buf)
    return '\n'.join(paras)

e98 = parse_long('/tmp/help_long_98.txt', 98)
for header, tl in e98:
    print('=== ' + header)
    print(repr(reconstruct(tl, 88)))
EOF"}

