/// Remove a leading `./` (current directory) component from a path.
pub fn strip_current_dir(path: &Path) -> &Path {
    path.strip_prefix(".").unwrap_or(path)
}

/// Make a path absolute (lexically) by prepending the current working directory.
pub fn absolute_path(path: &Path) -> io::Result<PathBuf> {
    let path_buf = path_absolute_form(path)?;
    Ok(path_buf)
}

/// Returns the absolute form of a path, without resolving symlinks.
pub fn path_absolute_form(path: &Path) -> io::Result<PathBuf> {
    if path.is_absolute() {
        return Ok(path.to_path_buf());
    }
    let path = path.strip_prefix(".").unwrap_or(path);
    env::current_dir().map(|cwd| cwd.join(path))
}

/// Check whether a path exists and is a directory (following symlinks).
pub fn is_existing_directory(path: &Path) -> bool {
    // Note: we do not use `Path::is_dir` here, so that a trailing slash on a
    // symlink to a directory is handled the same way as the original tool.
    path.is_dir() && (path.file_name().is_some() || path.canonicalize().is_ok())
}

/// Check whether a path points to an empty file or an empty directory.
pub fn is_empty(entry: &DirEntry) -> bool {
    if let Some(file_type) = entry.file_type() {
        if file_type.is_dir() {
            if let Ok(mut entries) = fs::read_dir(entry.path()) {
                entries.next().is_none()
            } else {
                false
            }
        } else if file_type.is_file() {
            entry.metadata().map(|m| m.len() == 0).unwrap_or(false)
        } else {
            false
        }
    } else {
        false
    }
}

/// Check whether the file at `path` may be executed by the current user.
pub fn is_executable(path: &Path) -> bool {
    let Ok(cpath) = CString::new(path.as_os_str().as_bytes()) else {
        return false;
    };
    // SAFETY: `cpath` is a valid NUL-terminated string.
    let rc = unsafe { libc::faccessat(libc::AT_FDCWD, cpath.as_ptr(), libc::X_OK, libc::AT_EACCESS) };
    rc == 0
}

/// Convert an `OsStr` to bytes (unix).
pub fn osstr_to_bytes(input: &OsStr) -> Cow<'_, [u8]> {
    Cow::Borrowed(input.as_bytes())
}

/// Remove the file extension from a path (after removing a leading `./`).
pub fn remove_extension(path: &Path) -> PathBuf {
    let path = strip_current_dir(path);
    let dirname = path.parent();
    let stem = path.file_stem();

    match (dirname, stem) {
        (Some(dir), Some(stem)) => {
            let mut buf = path.to_path_buf();
            if path.extension().is_some() {
                buf = dir.join(stem);
                // Preserve the original representation of the parent (e.g. doubled separators)
                // by truncating the original path instead of rebuilding it.
                let orig = path.as_os_str().as_bytes();
                let ext_len = path.extension().map(|e| e.as_bytes().len() + 1).unwrap_or(0);
                if orig.len() >= ext_len {
                    buf = PathBuf::from(OsStr::from_bytes(&orig[..orig.len() - ext_len]));
                }
            }
            buf
        }
        _ => path.to_path_buf(),
    }
}

