//! Filtering by modification time.

use std::time::{Duration, SystemTime, UNIX_EPOCH};

use jiff::civil::DateTime;
use jiff::tz::TimeZone;
use jiff::{Span, Timestamp, Zoned};

/// Filter based on time ranges.
#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum TimeFilter {
    Before(SystemTime),
    After(SystemTime),
}

impl TimeFilter {
    fn from_str(ref_time: &SystemTime, s: &str) -> Option<SystemTime> {
        // Durations ("10h", "2 weeks", "1d ago", ISO 8601 durations, ...)
        if let Ok(span) = s.parse::<Span>() {
            let now = Zoned::try_from(*ref_time).ok()?;
            let then = now.checked_sub(span).ok()?;
            return SystemTime::try_from(then).ok();
        }

        // RFC 3339 / ISO 8601 timestamps with offset
        if let Ok(ts) = s.parse::<Timestamp>() {
            return SystemTime::try_from(ts).ok();
        }

        // Local date / date-time
        if let Ok(dt) = s.parse::<DateTime>() {
            let zoned = dt.to_zoned(TimeZone::system()).ok()?;
            return SystemTime::try_from(zoned).ok();
        }

        // Seconds since the Unix epoch
        let secs = s.strip_prefix('@')?.parse::<u64>().ok()?;
        UNIX_EPOCH.checked_add(Duration::from_secs(secs))
    }

    pub fn before(ref_time: &SystemTime, s: &str) -> Option<TimeFilter> {
        TimeFilter::from_str(ref_time, s).map(TimeFilter::Before)
    }

    pub fn after(ref_time: &SystemTime, s: &str) -> Option<TimeFilter> {
        TimeFilter::from_str(ref_time, s).map(TimeFilter::After)
    }

    pub fn applies_to(&self, t: &SystemTime) -> bool {
        match self {
            TimeFilter::Before(limit) => t < limit,
            TimeFilter::After(limit) => t > limit,
        }
    }
}
