//! Helpers for inspecting regular expression patterns.

use regex_syntax::hir::{Hir, HirKind, Look};
use regex_syntax::ParserBuilder;

/// Determine if a regex pattern contains a literal uppercase character.
pub fn pattern_has_uppercase_char(pattern: &str) -> bool {
    let mut parser = ParserBuilder::new().utf8(false).build();

    parser
        .parse(pattern)
        .map(|hir| hir_has_uppercase_char(&hir))
        .unwrap_or(false)
}

/// Determine if a regex HIR contains a literal uppercase character.
fn hir_has_uppercase_char(hir: &Hir) -> bool {
    use regex_syntax::hir::Class;

    match hir.kind() {
        HirKind::Literal(literal) => {
            let bytes = &literal.0;
            match std::str::from_utf8(bytes) {
                Ok(s) => s.chars().any(|c| c.is_uppercase()),
                Err(_) => bytes.iter().any(|b| b.is_ascii_uppercase()),
            }
        }
        HirKind::Class(Class::Unicode(ranges)) => ranges
            .iter()
            .any(|r| r.start().is_uppercase() || r.end().is_uppercase()),
        HirKind::Class(Class::Bytes(ranges)) => ranges
            .iter()
            .any(|r| r.start().is_ascii_uppercase() || r.end().is_ascii_uppercase()),
        HirKind::Capture(c) => hir_has_uppercase_char(&c.sub),
        HirKind::Repetition(r) => hir_has_uppercase_char(&r.sub),
        HirKind::Concat(hirs) | HirKind::Alternation(hirs) => hirs.iter().any(hir_has_uppercase_char),
        _ => false,
    }
}

/// Determine if a regex pattern only matches strings starting with a literal dot (hidden files).
