//! Parsing of `LS_COLORS` and lookup of styles for filesystem entries.

use std::collections::HashMap;
use std::fs::Metadata;
use std::os::unix::fs::{FileTypeExt, MetadataExt, PermissionsExt};
use std::path::Path;

use crate::default_theme::DEFAULT_THEME;

/// A terminal color.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Color {
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    Fixed(u8),
    Rgb(u8, u8, u8),
}

impl Color {
    fn from_basic(n: u8) -> Color {
        match n {
            0 => Color::Black,
            1 => Color::Red,
            2 => Color::Green,
            3 => Color::Yellow,
            4 => Color::Blue,
            5 => Color::Magenta,
            6 => Color::Cyan,
            _ => Color::White,
        }
    }

    fn write_code(&self, out: &mut String, base: u8) {
        use std::fmt::Write;
        match *self {
            Color::Black => write!(out, "{}", base).unwrap(),
            Color::Red => write!(out, "{}", base + 1).unwrap(),
            Color::Green => write!(out, "{}", base + 2).unwrap(),
            Color::Yellow => write!(out, "{}", base + 3).unwrap(),
            Color::Blue => write!(out, "{}", base + 4).unwrap(),
            Color::Magenta => write!(out, "{}", base + 5).unwrap(),
            Color::Cyan => write!(out, "{}", base + 6).unwrap(),
            Color::White => write!(out, "{}", base + 7).unwrap(),
            Color::Fixed(n) => write!(out, "{};5;{}", base + 8, n).unwrap(),
            Color::Rgb(r, g, b) => write!(out, "{};2;{};{};{}", base + 8, r, g, b).unwrap(),
        }
    }
}

/// Font attributes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct FontStyle {
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
    pub underline: bool,
    pub blink: bool,
    pub reverse: bool,
    pub hidden: bool,
    pub strikethrough: bool,
}

/// A text style: optional colors and font attributes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Style {
    pub foreground: Option<Color>,
    pub background: Option<Color>,
    pub font_style: FontStyle,
}

impl Style {
    /// Parse an ANSI SGR sequence such as `01;34` or `38;5;81`.
    pub fn from_ansi_sequence(code: &str) -> Option<Style> {
        let mut style = Style::default();
        let mut tokens = code.split(';').map(|t| t.parse::<u8>());

        while let Some(token) = tokens.next() {
            let n = token.ok()?;
            match n {
                0 => style.font_style = FontStyle::default(),
                1 => style.font_style.bold = true,
                2 => style.font_style.dimmed = true,
                3 => style.font_style.italic = true,
                4 => style.font_style.underline = true,
                5 | 6 => style.font_style.blink = true,
                7 => style.font_style.reverse = true,
                8 => style.font_style.hidden = true,
                9 => style.font_style.strikethrough = true,
                22 => {
                    style.font_style.bold = false;
                    style.font_style.dimmed = false;
                }
                23 => style.font_style.italic = false,
                24 => style.font_style.underline = false,
                25 => style.font_style.blink = false,
                27 => style.font_style.reverse = false,
                28 => style.font_style.hidden = false,
                29 => style.font_style.strikethrough = false,
                30..=37 => style.foreground = Some(Color::from_basic(n - 30)),
                38 => style.foreground = Some(parse_extended_color(&mut tokens)?),
                39 => style.foreground = None,
                40..=47 => style.background = Some(Color::from_basic(n - 40)),
                48 => style.background = Some(parse_extended_color(&mut tokens)?),
                49 => style.background = None,
                90..=97 => style.foreground = Some(Color::Fixed(8 + (n - 90))),
                100..=107 => style.background = Some(Color::Fixed(8 + (n - 100))),
                _ => {}
            }
        }

        Some(style)
    }

    /// Whether this style has no effect at all.
    pub fn is_plain(&self) -> bool {
        self.foreground.is_none()
            && self.background.is_none()
            && self.font_style == FontStyle::default()
    }

    /// The ANSI escape sequence enabling this style (empty if plain).
    pub fn prefix(&self) -> String {
        if self.is_plain() {
            return String::new();
        }
        let mut out = String::from("\x1b[");
        let mut first = true;
        let mut push = |out: &mut String, code: &str| {
            if !first {
                out.push(';');
            }
            first = false;
            out.push_str(code);
        };
        let fs = &self.font_style;
        if fs.bold {
            push(&mut out, "1");
        }
        if fs.dimmed {
            push(&mut out, "2");
        }
        if fs.italic {
            push(&mut out, "3");
        }
        if fs.underline {
            push(&mut out, "4");
        }
        if fs.blink {
            push(&mut out, "5");
        }
        if fs.reverse {
            push(&mut out, "7");
        }
        if fs.hidden {
            push(&mut out, "8");
        }
        if fs.strikethrough {
            push(&mut out, "9");
        }
        if let Some(bg) = &self.background {
            let mut code = String::new();
            bg.write_code(&mut code, 40);
            push(&mut out, &code);
        }
        if let Some(fg) = &self.foreground {
            let mut code = String::new();
            fg.write_code(&mut code, 30);
            push(&mut out, &code);
        }
        out.push('m');
        out
    }

    /// The ANSI reset sequence (empty if plain).
    pub fn suffix(&self) -> &'static str {
        if self.is_plain() {
            ""
        } else {
            "\x1b[0m"
        }
    }

    /// Wrap `text` in this style.
    pub fn paint(&self, text: &str) -> String {
        if self.is_plain() {
            return text.to_string();
        }
        let mut out = self.prefix();
        out.push_str(text);
        out.push_str(self.suffix());
        out
    }
}

fn parse_extended_color<I>(tokens: &mut I) -> Option<Color>
where
    I: Iterator<Item = Result<u8, std::num::ParseIntError>>,
{
    match tokens.next()?.ok()? {
        5 => Some(Color::Fixed(tokens.next()?.ok()?)),
        2 => {
            let r = tokens.next()?.ok()?;
            let g = tokens.next()?.ok()?;
            let b = tokens.next()?.ok()?;
            Some(Color::Rgb(r, g, b))
        }
        _ => None,
    }
}

/// File type indicators as used by `LS_COLORS`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Indicator {
    Normal,
    RegularFile,
    Directory,
    SymbolicLink,
    FIFO,
    Socket,
    Door,
    BlockDevice,
    CharacterDevice,
    OrphanedSymbolicLink,
    MissingFile,
    Setuid,
    Setgid,
    Capabilities,
    StickyAndOtherWritable,
    OtherWritable,
    Sticky,
    ExecutableFile,
    MultipleHardLinks,
    LeftCode,
    RightCode,
    EndCode,
    Reset,
    ClearLine,
}

impl Indicator {
    pub fn from(indicator: &str) -> Option<Indicator> {
        Some(match indicator {
            "no" => Indicator::Normal,
            "fi" => Indicator::RegularFile,
            "di" => Indicator::Directory,
            "ln" => Indicator::SymbolicLink,
            "pi" => Indicator::FIFO,
            "so" => Indicator::Socket,
            "do" => Indicator::Door,
            "bd" => Indicator::BlockDevice,
            "cd" => Indicator::CharacterDevice,
            "or" => Indicator::OrphanedSymbolicLink,
            "mi" => Indicator::MissingFile,
            "su" => Indicator::Setuid,
            "sg" => Indicator::Setgid,
            "ca" => Indicator::Capabilities,
            "tw" => Indicator::StickyAndOtherWritable,
            "ow" => Indicator::OtherWritable,
            "st" => Indicator::Sticky,
            "ex" => Indicator::ExecutableFile,
            "mh" => Indicator::MultipleHardLinks,
            "lc" => Indicator::LeftCode,
            "rc" => Indicator::RightCode,
            "ec" => Indicator::EndCode,
            "rs" => Indicator::Reset,
            "cl" => Indicator::ClearLine,
            _ => return None,
        })
    }
}

/// Colorization rules derived from `LS_COLORS`.
#[derive(Debug, Clone)]
pub struct LsColors {
    indicator_mapping: HashMap<Indicator, Option<Style>>,
    /// Suffix patterns (without the leading `*`) in definition order.
    suffix_mapping: Vec<(String, Option<Style>)>,
}

/// Basic defaults that apply whenever `LS_COLORS` is set in the environment.
const BASE_DEFAULTS: &str = "di=01;34:ln=01;36:ex=01;32:su=37;41:sg=30;43:tw=30;42:ow=34;42:\
                             st=37;44:pi=33:so=01;35:bd=01;33:cd=01;33:do=01;35";

impl LsColors {
    fn empty() -> Self {
        LsColors {
            indicator_mapping: HashMap::new(),
            suffix_mapping: Vec::new(),
        }
    }

    /// Construct the rules from the `LS_COLORS` environment variable, if set.
    pub fn from_env() -> Option<Self> {
        std::env::var("LS_COLORS").ok().map(|s| Self::from_string(&s))
    }

    /// Construct the rules from a `LS_COLORS`-formatted string (on top of the basic defaults).
    pub fn from_string(input: &str) -> Self {
        let mut lscolors = LsColors::empty();
        lscolors.add_from_string(BASE_DEFAULTS);
        lscolors.add_from_string(input);
        lscolors
    }

    /// The built-in theme used when `LS_COLORS` is not set.
    pub fn default_theme() -> Self {
        let mut lscolors = LsColors::empty();
        lscolors.add_from_string(DEFAULT_THEME);
        lscolors
    }

    fn add_from_string(&mut self, input: &str) {
        for entry in input.split(':') {
            let mut parts = entry.split('=');
            if let (Some(key), Some(value)) = (parts.next(), parts.next()) {
                let style = Style::from_ansi_sequence(value);
                if let Some(suffix) = key.strip_prefix('*') {
                    self.suffix_mapping.push((suffix.to_string(), style));
                } else if let Some(indicator) = Indicator::from(key) {
                    self.indicator_mapping.insert(indicator, style);
                }
            }
        }
    }

    /// Suffix patterns are matched case-insensitively unless two patterns that
    /// differ only in case map to different styles.
    fn suffix_matching_is_case_sensitive(&self) -> bool {
        let mut seen: HashMap<String, (&str, Option<Style>)> = HashMap::new();
        for (suffix, style) in &self.suffix_mapping {
            let lower = suffix.to_lowercase();
            match seen.get(&lower) {
                Some((other, other_style)) => {
                    if *other != suffix.as_str() && other_style != style {
                        return true;
                    }
                }
                None => {
                    seen.insert(lower, (suffix.as_str(), *style));
                }
            }
        }
        false
    }

    /// Look up the style for a file type indicator (falling back to `no`).
    pub fn style_for_indicator(&self, indicator: Indicator) -> Option<&Style> {
        self.indicator_mapping
            .get(&indicator)
            .and_then(|s| s.as_ref())
            .or_else(|| {
                self.indicator_mapping
                    .get(&Indicator::Normal)
                    .and_then(|s| s.as_ref())
            })
    }

    fn style_for_indicator_strict(&self, indicator: Indicator) -> Option<&Style> {
        self.indicator_mapping.get(&indicator).and_then(|s| s.as_ref())
    }

    fn style_for_suffix(&self, file_name: &str) -> Option<&Style> {
        let case_sensitive = self.suffix_matching_is_case_sensitive();
        let lower_name;
        let name: &str = if case_sensitive {
            file_name
        } else {
            lower_name = file_name.to_lowercase();
            &lower_name
        };
        for (suffix, style) in self.suffix_mapping.iter().rev() {
            let matched = if case_sensitive {
                name.ends_with(suffix.as_str())
            } else {
                name.ends_with(&suffix.to_lowercase())
            };
            if matched {
                return style.as_ref();
            }
        }
        None
    }

    /// Determine the style for a path with the given (symlink-aware) metadata.
    pub fn style_for_path_with_metadata(
        &self,
        path: &Path,
        metadata: Option<&Metadata>,
    ) -> Option<&Style> {
        let file_name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            .unwrap_or_default();

        let Some(md) = metadata else {
            return self
                .style_for_suffix(&file_name)
                .or_else(|| self.style_for_indicator(Indicator::RegularFile));
        };

        let ft = md.file_type();
        if ft.is_symlink() {
            let orphaned = std::fs::metadata(path).is_err();
            if orphaned {
                if let Some(style) = self.style_for_indicator_strict(Indicator::OrphanedSymbolicLink) {
                    return Some(style);
                }
            }
            return self.style_for_indicator(Indicator::SymbolicLink);
        }
        if ft.is_dir() {
            let mode = md.permissions().mode();
            let sticky = mode & 0o1000 != 0;
            let other_writable = mode & 0o002 != 0;
            if sticky && other_writable {
                if let Some(style) = self.style_for_indicator_strict(Indicator::StickyAndOtherWritable) {
                    return Some(style);
                }
            }
            if other_writable {
                if let Some(style) = self.style_for_indicator_strict(Indicator::OtherWritable) {
                    return Some(style);
                }
            }
            if sticky {
                if let Some(style) = self.style_for_indicator_strict(Indicator::Sticky) {
                    return Some(style);
                }
            }
            return self.style_for_indicator(Indicator::Directory);
        }
        if ft.is_fifo() {
            return self.style_for_indicator(Indicator::FIFO);
        }
        if ft.is_socket() {
            return self.style_for_indicator(Indicator::Socket);
        }
        if ft.is_block_device() {
            return self.style_for_indicator(Indicator::BlockDevice);
        }
        if ft.is_char_device() {
            return self.style_for_indicator(Indicator::CharacterDevice);
        }

        // Regular file.
        let mode = md.permissions().mode();
        if mode & 0o4000 != 0 {
            if let Some(style) = self.style_for_indicator_strict(Indicator::Setuid) {
                return Some(style);
            }
        }
        if mode & 0o2000 != 0 {
            if let Some(style) = self.style_for_indicator_strict(Indicator::Setgid) {
                return Some(style);
            }
        }
        if mode & 0o111 != 0 {
            if let Some(style) = self.style_for_indicator_strict(Indicator::ExecutableFile) {
                return Some(style);
            }
        }
        if md.nlink() > 1 {
            if let Some(style) = self.style_for_indicator_strict(Indicator::MultipleHardLinks) {
                return Some(style);
            }
        }
        if let Some(style) = self.style_for_suffix(&file_name) {
            return Some(style);
        }
        self.style_for_indicator(Indicator::RegularFile)
    }
}
EOF
echo ok"}

