//! Output templates with `{}`-style placeholders (used by `--format`, `--exec` and `--exec-batch`).

use std::ffi::OsString;
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::path::{Path, MAIN_SEPARATOR};

use crate::filesystem::{remove_extension, strip_current_dir};

/// A token in a template.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    /// `{}`: the full path
    Placeholder,
    /// `{/}`: the basename
    Basename,
    /// `{//}`: the parent directory
    Parent,
    /// `{.}`: the path without its extension
    NoExt,
    /// `{/.}`: the basename without its extension
    BasenameNoExt,
    /// literal text
    Text(String),
}

/// A parsed template.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FormatTemplate(Vec<Token>);

impl FormatTemplate {
    pub fn has_tokens(&self) -> bool {
        self.0.iter().any(|t| !matches!(t, Token::Text(_)))
    }

    /// Parse a template string. `{{` and `}}` are escapes for literal braces.
    pub fn parse(input: &str) -> Self {
        let mut tokens = Vec::new();
        let mut rest = input;

        loop {
            // Find the leftmost escape sequence.
            let open = rest.find("{{");
            let close = rest.find("}}");
            let next = match (open, close) {
                (Some(o), Some(c)) => Some(std::cmp::min(o, c)),
                (Some(o), None) => Some(o),
                (None, Some(c)) => Some(c),
                (None, None) => None,
            };
            match next {
                Some(idx) => {
                    let (before, after) = rest.split_at(idx);
                    Self::parse_placeholders(before, &mut tokens);
                    let brace = if after.starts_with("{{") { "{" } else { "}" };
                    push_text(&mut tokens, brace);
                    rest = &after[2..];
                }
                None => {
                    Self::parse_placeholders(rest, &mut tokens);
                    break;
                }
            }
        }

        FormatTemplate(tokens)
    }

    fn parse_placeholders(mut s: &str, tokens: &mut Vec<Token>) {
        const PLACEHOLDERS: [(&str, Token); 5] = [
            ("{}", Token::Placeholder),
            ("{/}", Token::Basename),
            ("{//}", Token::Parent),
            ("{.}", Token::NoExt),
            ("{/.}", Token::BasenameNoExt),
        ];
        while !s.is_empty() {
            // find next '{'
            let Some(brace) = s.find('{') else {
                push_text(tokens, s);
                break;
            };
            let (before, after) = s.split_at(brace);
            let mut matched = None;
            for (pat, tok) in PLACEHOLDERS.iter() {
                if after.starts_with(pat) {
                    matched = Some((pat.len(), tok.clone()));
                    break;
                }
            }
            match matched {
                Some((len, tok)) => {
                    push_text(tokens, before);
                    tokens.push(tok);
                    s = &after[len..];
                }
                None => {
                    push_text(tokens, &s[..brace + 1]);
                    s = &after[1..];
                }
            }
        }
    }

    /// Generate the output for a single path.
    pub fn generate(&self, path: &Path, path_separator: Option<&str>) -> OsString {
        let mut out = Vec::new();
        for token in &self.0 {
            match token {
                Token::Text(t) => out.extend_from_slice(t.as_bytes()),
                Token::Placeholder => out.extend_from_slice(&with_separator(path.as_os_str().as_bytes(), path_separator)),
                Token::Basename => out.extend_from_slice(&with_separator(basename(path), path_separator)),
                Token::Parent => out.extend_from_slice(&with_separator(dirname(path).as_bytes(), path_separator)),
                Token::NoExt => out.extend_from_slice(&with_separator(remove_extension(path).as_os_str().as_bytes(), path_separator)),
                Token::BasenameNoExt => out.extend_from_slice(&with_separator(basename(&remove_extension(path)), path_separator)),
            }
        }
        OsString::from_vec(out)
    }
}

fn push_text(tokens: &mut Vec<Token>, text: &str) {
    if text.is_empty() {
        return;
    }
    if let Some(Token::Text(last)) = tokens.last_mut() {
        last.push_str(text);
    } else {
        tokens.push(Token::Text(text.to_string()));
    }
}

fn basename(path: &Path) -> &[u8] {
    path.file_name().map(|n| n.as_bytes()).unwrap_or_else(|| path.as_os_str().as_bytes())
}

fn dirname(path: &Path) -> OsString {
    let path = strip_current_dir(path);
    match path.parent() {
        Some(p) if p.as_os_str().is_empty() => OsString::from("."),
        Some(p) => p.as_os_str().to_os_string(),
        None => path.as_os_str().to_os_string(),
    }
}

fn with_separator(bytes: &[u8], path_separator: Option<&str>) -> Vec<u8> {
    match path_separator {
        None => bytes.to_vec(),
        Some(sep) => {
            let s = String::from_utf8_lossy(bytes);
            s.replace(MAIN_SEPARATOR, sep).into_bytes()
        }
    }
}
EOF
