    path.file_name().map(|n| n.as_bytes()).unwrap_or_else(|| path.as_os_str().as_bytes())
}

fn dirname(path: &Path) -> OsString {
    let path = strip_current_dir(path);
    match path.parent() {
        Some(p) if p.as_os_str().is_empty() => OsString::from("."),
        Some(p) => p.as_os_str().to_os_string(),
        None => path.as_os_str().to_os_string(),
    }
}

fn with_separator(bytes: &[u8], path_separator: Option<&str>) -> Vec<u8> {
    match path_separator {
        None => bytes.to_vec(),
        Some(sep) => {
            let s = String::from_utf8_lossy(bytes);
            s.replace(MAIN_SEPARATOR, sep).into_bytes()
        }
    }
}
