use std::borrow::Cow;
use std::io::{self, Write};
use std::os::unix::ffi::OsStrExt;

use crate::config::Config;
use crate::dir_entry::DirEntry;
use crate::error::print_error;
use crate::exit_codes::ExitCode;
use crate::filesystem::replace_path_separator;
use crate::hyperlink;
use crate::lscolors::{Indicator, LsColors, Style};

/// Print a single entry; exits the process on I/O errors.
pub fn print_entry<W: Write>(stdout: &mut W, entry: &DirEntry, config: &Config) {
    let mut has_hyperlink = false;
    if config.hyperlink {
        if let Ok(()) = write!(stdout, "{}", hyperlink::start(entry.path())) {
            has_hyperlink = true;
        }
    }

    let r = if let Some(ref format) = config.format {
        print_entry_format(stdout, entry, config, format)
    } else if let Some(ref ls_colors) = config.ls_colors {
        print_entry_colorized(stdout, entry, config, ls_colors)
    } else {
        print_entry_uncolorized(stdout, entry, config)
    };

    let r = r.and_then(|()| {
        if has_hyperlink {
            write!(stdout, "{}", hyperlink::END)?;
        }
        if config.null_separator {
            stdout.write_all(b"\0")
        } else {
            stdout.write_all(b"\n")
        }
    });

    if let Err(e) = r {
        if e.kind() == io::ErrorKind::BrokenPipe {
            // Exit quietly in case of a broken pipe (e.g. 'fd ... | head -n 3').
            ExitCode::GeneralError.exit();
        } else {
            print_error(format!("Could not write to output: {}", e));
            ExitCode::GeneralError.exit();
        }
    }
}

fn print_entry_format<W: Write>(
    stdout: &mut W,
    entry: &DirEntry,
    config: &Config,
    format: &crate::fmt::FormatTemplate,
) -> io::Result<()> {
    let output = format.generate(entry.stripped_path(config), config.path_separator.as_deref());
    stdout.write_all(&String::from_utf8_lossy(output.as_bytes()).into_owned().into_bytes())
}

fn print_trailing_slash<W: Write>(
    stdout: &mut W,
    entry: &DirEntry,
    config: &Config,
    style: Option<&Style>,
) -> io::Result<()> {
    if entry.file_type().map_or(false, |ft| ft.is_dir()) {
        let sep = &config.actual_path_separator;
        match style {
            Some(style) => write!(stdout, "{}", style.paint(sep)),
            None => stdout.write_all(sep.as_bytes()),
        }?;
    }
    Ok(())
}

fn print_entry_colorized<W: Write>(
    stdout: &mut W,
    entry: &DirEntry,
    config: &Config,
    ls_colors: &LsColors,
) -> io::Result<()> {
    // Split the path between the parent and the last component
    let mut offset = 0;
    let path = entry.stripped_path(config);
    let path_str = path.to_string_lossy();

    if let Some(parent) = path.parent() {
        offset = parent.to_string_lossy().len();
        for c in path_str[offset..].chars() {
            if std::path::is_separator(c) {
                offset += c.len_utf8();
            } else {
                break;
            }
        }
    }

    let dir_style = ls_colors.style_for_indicator(Indicator::Directory);

    if offset > 0 {
        let mut parent_str = Cow::from(&path_str[..offset]);
        if let Some(ref separator) = config.path_separator {
            *parent_str.to_mut() = replace_path_separator(&parent_str, separator);
        }
        match dir_style {
            Some(style) => write!(stdout, "{}", style.paint(&parent_str))?,
            None => stdout.write_all(parent_str.as_bytes())?,
        }
    }

    let style = ls_colors.style_for_path_with_metadata(entry.path(), entry.metadata());
    let name = &path_str[offset..];
    match style {
        Some(style) => write!(stdout, "{}", style.paint(name))?,
        None => stdout.write_all(name.as_bytes())?,
    }

    print_trailing_slash(stdout, entry, config, dir_style)
}

fn print_entry_uncolorized<W: Write>(
    stdout: &mut W,
    entry: &DirEntry,
    config: &Config,
) -> io::Result<()> {
    let path = entry.stripped_path(config);
    if let Some(ref separator) = config.path_separator {
        let path_string = replace_path_separator(&path.to_string_lossy(), separator);
        stdout.write_all(path_string.as_bytes())?;
    } else {
        stdout.write_all(path.as_os_str().as_bytes())?;
    }
    print_trailing_slash(stdout, entry, config, None)
}
