//! Command execution (`--exec` and `--exec-batch`).

mod job;

use std::ffi::OsString;
use std::io::{self, Write};
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::{Arc, Mutex};

pub use self::job::{batch, job};

use crate::error::print_error;
use crate::exit_codes::ExitCode;
use crate::fmt::FormatTemplate;

/// Execution mode of the command(s).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ExecutionMode {
    /// Command is executed for each search result
    OneByOne,
    /// Command is run for a batch of results at once
    Batch,
}

/// A set of commands to run for every search result (or batch).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CommandSet {
    mode: ExecutionMode,
    commands: Vec<CommandTemplate>,
}

/// Errors that may occur when constructing a command set.
#[derive(Debug)]
pub enum CommandSetError {
    MultiplePlaceholders,
    NonFixedExecutable,
}

impl std::fmt::Display for CommandSetError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            CommandSetError::MultiplePlaceholders => {
                write!(f, "Only one placeholder allowed for batch commands")
            }
            CommandSetError::NonFixedExecutable => {
                write!(f, "First argument of exec-batch is expected to be a fixed executable")
            }
        }
    }
}

impl CommandSet {
    pub fn new<I, S>(input: I) -> Self
    where
        I: IntoIterator<Item = Vec<S>>,
        S: AsRef<str>,
    {
        CommandSet {
            mode: ExecutionMode::OneByOne,
            commands: input.into_iter().map(CommandTemplate::new).collect(),
        }
    }

    pub fn new_batch<I, S>(input: I) -> Result<Self, CommandSetError>
    where
        I: IntoIterator<Item = Vec<S>>,
        S: AsRef<str>,
    {
        let mut commands = Vec::new();
        for args in input {
            let cmd = CommandTemplate::new(args);
            if cmd.args[0].has_tokens() {
                return Err(CommandSetError::NonFixedExecutable);
            }
            if cmd.number_of_tokens() > 1 {
                return Err(CommandSetError::MultiplePlaceholders);
            }
            commands.push(cmd);
        }
        Ok(CommandSet {
            mode: ExecutionMode::Batch,
            commands,
        })
    }

    pub fn in_batch_mode(&self) -> bool {
        self.mode == ExecutionMode::Batch
    }

    /// Execute the commands for a single path.
    pub fn execute(
        &self,
        input: &Path,
        path_separator: Option<&str>,
        out_perm: &Mutex<()>,
        buffer_output: bool,
        null_separator: bool,
    ) -> ExitCode {
        let commands = self.commands.iter().map(|c| c.generate(input, path_separator));
        execute_commands(commands, out_perm, buffer_output, null_separator)
    }

    /// Execute the commands with batches of paths.
    pub fn execute_batch<I>(&self, paths: I, limit: usize, path_separator: Option<&str>) -> ExitCode
    where
        I: IntoIterator<Item = std::path::PathBuf>,
    {
        let mut builders: Vec<CommandBuilder> = self
            .commands
            .iter()
            .map(|c| CommandBuilder::new(c, limit))
            .collect();

        for path in paths {
            for builder in &mut builders {
                if let Err(e) = builder.push(&path, path_separator) {
                    return handle_cmd_error(Some(&builder.program), e);
                }
            }
        }

        let mut exit_code = ExitCode::Success;
        for builder in &mut builders {
            match builder.finish() {
                Ok(code) => exit_code = crate::exit_codes::merge_exitcodes([exit_code, code]),
                Err(e) => return handle_cmd_error(Some(&builder.program), e),
            }
        }
        exit_code
    }
}

/// Represents a template for a single command.
#[derive(Debug, Clone, PartialEq, Eq)]
struct CommandTemplate {
    args: Vec<FormatTemplate>,
}

impl CommandTemplate {
    fn new<I, S>(input: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let mut args: Vec<FormatTemplate> = input
            .into_iter()
            .map(|arg| FormatTemplate::parse(arg.as_ref()))
            .collect();

        // If a placeholder token was not supplied, append one at the end of the command.
        if !args.iter().any(|a| a.has_tokens()) {
            args.push(FormatTemplate::parse("{}"));
        }

        CommandTemplate { args }
    }

    fn number_of_tokens(&self) -> usize {
        self.args.iter().filter(|a| a.has_tokens()).count()
    }

    /// Generate a command for the given path.
    fn generate(&self, input: &Path, path_separator: Option<&str>) -> Command {
        let mut args = self.args.iter().map(|a| a.generate(input, path_separator));
        let program = args.next().unwrap_or_default();
        let mut cmd = Command::new(program);
        cmd.args(args);
        cmd
    }
}

/// Accumulates arguments for batch execution.
struct CommandBuilder<'a> {
    template: &'a CommandTemplate,
    program: OsString,
    pre_args: Vec<OsString>,
    path_arg: &'a FormatTemplate,
    post_args: Vec<OsString>,
    paths: Vec<OsString>,
    limit: usize,
    max_bytes: usize,
    bytes: usize,
    exit_code: ExitCode,
}

impl<'a> CommandBuilder<'a> {
    fn new(template: &'a CommandTemplate, limit: usize) -> Self {
        let program = template.args[0]
            .generate(Path::new(""), None);
        let mut pre_args = Vec::new();
        let mut post_args = Vec::new();
        let mut path_arg = None;
        for arg in &template.args[1..] {
            if arg.has_tokens() {
                path_arg = Some(arg);
            } else {
                let value = arg.generate(Path::new(""), None);
                if path_arg.is_none() {
                    pre_args.push(value);
                } else {
                    post_args.push(value);
                }
            }
        }
        let path_arg = path_arg.unwrap_or(&template.args[template.args.len() - 1]);
        let fixed_bytes: usize = program.len()
            + pre_args.iter().map(|a| a.len() + 1 + std::mem::size_of::<usize>()).sum::<usize>()
            + post_args.iter().map(|a| a.len() + 1 + std::mem::size_of::<usize>()).sum::<usize>();
        CommandBuilder {
            template,
            program,
            pre_args,
            path_arg,
            post_args,
            paths: Vec::new(),
            limit,
            max_bytes: max_command_line_bytes().saturating_sub(fixed_bytes),
            bytes: 0,
            exit_code: ExitCode::Success,
        }
    }

    fn push(&mut self, path: &Path, path_separator: Option<&str>) -> io::Result<()> {
        let arg = self.path_arg.generate(path, path_separator);
        let needed = arg.len() + 1 + std::mem::size_of::<usize>();
        if (self.limit > 0 && self.paths.len() >= self.limit)
            || (!self.paths.is_empty() && self.bytes + needed > self.max_bytes)
        {
            self.run()?;
        }
        self.bytes += needed;
        self.paths.push(arg);
        Ok(())
    }

    fn run(&mut self) -> io::Result<()> {
        if self.paths.is_empty() {
            return Ok(());
        }
        let mut cmd = Command::new(&self.program);
        cmd.args(&self.pre_args);
        cmd.args(self.paths.drain(..));
        cmd.args(&self.post_args);
        self.bytes = 0;
        let status = cmd.status()?;
        if !status.success() {
            self.exit_code = ExitCode::GeneralError;
        }
        let _ = self.template;
        Ok(())
    }

    fn finish(&mut self) -> io::Result<ExitCode> {
        self.run()?;
        Ok(self.exit_code)
    }
}

fn max_command_line_bytes() -> usize {
    // SAFETY: sysconf is always safe to call.
    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    let arg_max = if arg_max <= 0 { 128 * 1024 } else { arg_max as usize };
    // Leave room for the environment and some slack, like xargs does.
    let env_size: usize = std::env::vars_os()
        .map(|(k, v)| k.len() + v.len() + 2 + std::mem::size_of::<usize>())
        .sum();
    arg_max.saturating_sub(env_size).saturating_sub(2048).max(4096)
}

/// Buffers the output of commands so that it can be written atomically.
struct OutputBuffer<'a> {
    out_perm: &'a Mutex<()>,
    stdouts: Vec<Vec<u8>>,
    stderrs: Vec<Vec<u8>>,
}

impl<'a> OutputBuffer<'a> {
    fn new(out_perm: &'a Mutex<()>) -> Self {
        Self {
            out_perm,
            stdouts: Vec::new(),
            stderrs: Vec::new(),
        }
    }

    fn push(&mut self, stdout: Vec<u8>, stderr: Vec<u8>) {
        self.stdouts.push(stdout);
        self.stderrs.push(stderr);
    }

    fn write(self, null_separator: bool) {
        // Avoid taking the lock if there is nothing to do.
