    set_working_dir(&matches)?;
    let search_paths = extract_search_paths(&matches)?;

    ensure_search_pattern_is_not_a_directory(&matches, &search_paths)?;
    let pattern_regexps = extract_patterns(&matches)?;

    let config = construct_config(&mut cmd, &matches, &pattern_regexps)?;

    ensure_use_hidden_option_for_leading_dot_pattern(&config, &pattern_regexps)?;

    let regexps = pattern_regexps
        .iter()
        .map(|pat| build_regex(pat, &config))
        .collect::<Result<Vec<_>, String>>()?;

    walk::scan(&search_paths, Arc::new(regexps), Arc::new(config))
}

fn set_working_dir(matches: &ArgMatches) -> Result<(), String> {
    if let Some(base_directory) = matches.get_one::<PathBuf>("base_directory") {
        if !filesystem::is_existing_directory(base_directory) {
            return Err(format!(
                "The '--base-directory' path '{}' is not a directory.",
                base_directory.to_string_lossy()
            ));
        }
        env::set_current_dir(base_directory).map_err(|e| {
            format!(
                "Could not set '{}' as the current working directory: {}",
                base_directory.to_string_lossy(),
                e
            )
        })?;
    }
    Ok(())
}

/// Normalize a search path: canonicalize for absolute output, otherwise keep as given
/// (with the special case of "." being represented as "./").
fn normalize_path(matches: &ArgMatches, path: &Path) -> PathBuf {
    if matches.get_flag("absolute_path") {
        match path.canonicalize() {
            Ok(p) => p,
            Err(_) => filesystem::absolute_path(path).unwrap_or_else(|_| path.to_path_buf()),
        }
    } else if path == Path::new(".") {
        // Represent "." as "./" so that results are shown with a "./" prefix.
        PathBuf::from("./")
    } else {
        path.to_path_buf()
    }
}

fn ensure_current_directory_exists(current_directory: &Path) -> Result<(), String> {
    if filesystem::is_existing_directory(current_directory) {
        Ok(())
    } else {
        Err("Could not retrieve current directory (has it been deleted?).".to_string())
    }
}

fn extract_search_paths(matches: &ArgMatches) -> Result<Vec<PathBuf>, String> {
    let positional: Vec<&PathBuf> = matches
        .get_many::<PathBuf>("path")
        .map(|v| v.collect())
        .unwrap_or_default();
    let search_path_opt: Vec<&PathBuf> = matches
        .get_many::<PathBuf>("search_path")
        .map(|v| v.collect())
        .unwrap_or_default();

    let paths: Vec<&PathBuf> = if !positional.is_empty() {
        positional
    } else if !search_path_opt.is_empty() {
        search_path_opt
    } else {
        let current_directory = Path::new(".");
        ensure_current_directory_exists(current_directory)?;
        return Ok(vec![normalize_path(matches, current_directory)]);
    };

    let search_paths: Vec<PathBuf> = paths
        .iter()
        .filter_map(|path| {
            if filesystem::is_existing_directory(path) {
                Some(normalize_path(matches, path))
            } else {
                print_error(format!(
                    "Search path '{}' is not a directory.",
                    path.to_string_lossy()
                ));
                None
            }
        })
        .collect();

    if search_paths.is_empty() {
        return Err("No valid search paths given.".to_string());
    }

    Ok(search_paths)
}

/// Detect if the user accidentally supplied a path instead of a search pattern.
fn ensure_search_pattern_is_not_a_directory(
    matches: &ArgMatches,
    search_paths: &[PathBuf],
) -> Result<(), String> {
    let pattern = matches.get_one::<String>("pattern");
    let has_explicit_paths = matches.contains_id("path") || matches.contains_id("search_path");
    if let Some(pattern) = pattern {
        if !has_explicit_paths
            && !matches.get_flag("full_path")
            && pattern.contains(std::path::MAIN_SEPARATOR)
            && Path::new(pattern).is_dir()
            && search_paths.len() == 1
        {
            return Err(format!(
                "The search pattern '{pattern}' contains a path-separation character ('{sep}') \
                 and will not lead to any search results.\n\n\
                 If you want to search for all files inside the '{pattern}' directory, use a match-all pattern:\n\n  \
                 fd . '{pattern}'\n\n\
                 Instead, if you want your pattern to match the full file path, use:\n\n  \
                 fd --full-path '{pattern}'",
                sep = std::path::MAIN_SEPARATOR
            ));
        }
    }
    Ok(())
}

fn extract_patterns(matches: &ArgMatches) -> Result<Vec<String>, String> {
    let mut patterns: Vec<String> = Vec::new();
    if let Some(p) = matches.get_one::<String>("pattern") {
        patterns.push(p.clone());
    }
    if let Some(and) = matches.get_many::<String>("and") {
        patterns.extend(and.cloned());
    }
    if patterns.is_empty() {
        patterns.push(String::new());
    }

    let glob = matches.get_flag("glob");
    let fixed_strings = matches.get_flag("fixed_strings");

    patterns
        .iter()
        .map(|pattern| {
            if fixed_strings {
                Ok(regex::escape(pattern))
            } else if glob {
                let glob = globset::GlobBuilder::new(pattern)
                    .literal_separator(true)
                    .build()
                    .map_err(|e| e.to_string())?;
                Ok(glob.regex().to_owned())
            } else {
                Ok(pattern.clone())
            }
        })
        .collect()
}

fn ensure_use_hidden_option_for_leading_dot_pattern(
    config: &Config,
    pattern_regexps: &[String],
) -> Result<(), String> {
    if config.ignore_hidden
        && pattern_regexps
            .iter()
            .any(|pat| pattern_matches_strings_with_leading_dot(pat))
    {
        Err("The pattern(s) seems to only match files with a leading dot, but hidden files are \
             filtered by default. Consider adding -H/--hidden to search hidden files as well or \
             adjust your search pattern(s)."
            .to_string())
    } else {
        Ok(())
    }
}

fn build_regex(pattern_regex: &str, config: &Config) -> Result<regex::bytes::Regex, String> {
    RegexBuilder::new(pattern_regex)
        .case_insensitive(!config.case_sensitive)
        .dot_matches_new_line(true)
        .build()
        .map_err(|e| {
            format!(
                "{}\n\nNote: You can use the '--fixed-strings' option to search for a literal \
                 string instead of a regular expression. Alternatively, you can also use the \
                 '--glob' option to match on a glob pattern.",
                e
            )
        })
}

fn default_num_threads() -> NonZeroUsize {
    let fallback = NonZeroUsize::MIN;
    let limit = NonZeroUsize::new(DEFAULT_MAX_THREADS).unwrap();
    std::thread::available_parallelism()
        .unwrap_or(fallback)
        .min(limit)
}

fn construct_config(
    cmd: &mut clap::Command,
    matches: &ArgMatches,
    pattern_regexps: &[String],
) -> Result<Config, String> {
    // The search will be case-sensitive if the command line flag is set or
    // if any of the patterns has an uppercase character (smart case).
    let case_sensitive = !matches.get_flag("ignore_case")
        && (matches.get_flag("case_sensitive")
            || pattern_regexps
                .iter()
                .any(|pat| pattern_has_uppercase_char(pat)));

    let path_separator: Option<String> = matches
        .get_one::<String>("path_separator")
        .cloned()
        .or_else(filesystem::default_path_separator);
    let actual_path_separator = path_separator
        .clone()
        .unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
    check_path_separator_length(&path_separator)?;

    let unrestricted = matches.get_count("unrestricted") > 0;
    let hidden = matches.get_flag("hidden") || unrestricted;
    let no_ignore = matches.get_flag("no_ignore") || unrestricted;
    let no_ignore_vcs = matches.get_flag("no_ignore_vcs");

    let interactive_terminal = is_terminal(libc::STDOUT_FILENO);
    let colored_output = match matches
        .get_one::<String>("color")
        .map(|s| s.as_str())
        .unwrap_or("auto")
    {
        "always" => true,
        "never" => false,
        _ => {
            let no_color = env::var_os("NO_COLOR").map_or(false, |v| !v.is_empty());
            !no_color && interactive_terminal
        }
    };

    let hyperlink = match matches
        .get_one::<String>("hyperlink")
        .map(|s| s.as_str())
        .unwrap_or("never")
    {
        "always" => true,
        "never" => false,
        _ => colored_output,
    };

    let ls_colors = if colored_output {
        Some(LsColors::from_env().unwrap_or_else(LsColors::default_theme))
    } else {
        None
    };

    let command = extract_command(cmd, matches, colored_output)?;
    let has_command = command.is_some();

    let threads: usize = matches
        .get_one::<NonZeroUsize>("threads")
        .copied()
        .unwrap_or_else(default_num_threads)
        .get();

    let exact_depth = matches.get_one::<usize>("exact_depth").copied();
    let max_depth = matches.get_one::<usize>("max_depth").copied().or(exact_depth);
    let min_depth = matches.get_one::<usize>("min_depth").copied().or(exact_depth);

    let file_types = matches.get_many::<String>("filetype").map(|values| {
        let mut file_types = FileTypes::default();
        for value in values {
            match value.as_str() {
                "file" => file_types.files = true,
                "directory" => file_types.directories = true,
                "symlink" => file_types.symlinks = true,
                "block-device" => file_types.block_devices = true,
                "char-device" => file_types.char_devices = true,
                "executable" => {
                    file_types.executables_only = true;
                    file_types.files = true;
                }
                "empty" => file_types.empty_only = true,
                "socket" => file_types.sockets = true,
                "pipe" => file_types.pipes = true,
                _ => {}
            }
        }

        // If only 'empty' was specified, search for both files and directories:
        if file_types.empty_only && !(file_types.files || file_types.directories) {
            file_types.files = true;
            file_types.directories = true;
        }

        file_types
    });

    let extensions = matches.get_many::<String>("extension").map(|exts| {
        let patterns = exts
            .map(|e| e.trim_start_matches('.'))
            .map(|e| format!(r".+\.{}$", regex::escape(e)));
        RegexSetBuilder::new(patterns)
            .case_insensitive(true)
            .build()
            .expect("extension regex set")
    });

    let now = SystemTime::now();
    let mut time_constraints: Vec<TimeFilter> = Vec::new();
    if let Some(t) = matches.get_one::<String>("changed_within") {
        if let Some(f) = TimeFilter::after(&now, t) {
            time_constraints.push(f);
        } else {
            return Err(format!(
                "'{}' is not a valid date or duration. See 'fd --help'.",
                t
            ));
        }
    }
    if let Some(t) = matches.get_one::<String>("changed_before") {
        if let Some(f) = TimeFilter::before(&now, t) {
            time_constraints.push(f);
        } else {
            return Err(format!(
                "'{}' is not a valid date or duration. See 'fd --help'.",
                t
            ));
        }
    }

    let size_constraints: Vec<SizeFilter> = matches
        .get_many::<SizeFilter>("size")
        .map(|v| v.copied().collect())
        .unwrap_or_default();

    let owner_constraint: Option<OwnerFilter> = matches
        .get_one::<OwnerFilter>("owner")
        .copied()
        .and_then(OwnerFilter::filter_ignore);

    let null_separator = matches.get_flag("print0");
    let quiet = matches.get_flag("quiet");

    let max_results = if matches.get_flag("max_one_result") {
        Some(1)
    } else {
        matches
            .get_one::<usize>("max_results")
            .copied()
            .filter(|&m| m > 0)
    };

    let has_search_paths = matches.contains_id("path") || matches.contains_id("search_path");
    let strip_cwd_prefix = !has_search_paths
        && match matches
            .get_one::<String>("strip_cwd_prefix")
            .map(|s| s.as_str())
        {
            Some("always") => true,
            Some("never") => false,
            _ => !(null_separator || has_command),
        };

    let format = matches
        .get_one::<String>("format")
        .map(|f| FormatTemplate::parse(f));

    Ok(Config {
        case_sensitive,
        search_full_path: matches.get_flag("full_path"),
        ignore_hidden: !hidden,
        read_fdignore: !no_ignore,
        read_vcsignore: !no_ignore && !no_ignore_vcs,
        require_git_to_read_vcsignore: !matches.get_flag("no_require_git"),
        read_global_ignore: !no_ignore,
        read_parent_ignore: !matches.get_flag("no_ignore_parent"),
        follow_links: matches.get_flag("follow"),
        one_file_system: matches.get_flag("one_file_system"),
        null_separator,
        quiet,
        max_depth,
        min_depth,
        prune: matches.get_flag("prune"),
        threads,
        max_buffer_time: None,
        ls_colors,
        interactive_terminal,
        file_types,
        extensions,
        format,
        command: command.map(Arc::new),
        batch_size: matches.get_one::<usize>("batch_size").copied().unwrap_or(0),
        exclude_patterns: matches
            .get_many::<String>("exclude")
            .map(|v| v.map(|p| format!("!{}", p)).collect())
            .unwrap_or_default(),
        ignore_contain: matches
            .get_many::<String>("ignore_contain")
            .map(|v| v.map(PathBuf::from).collect())
            .unwrap_or_default(),
        ignore_files: matches
            .get_many::<String>("ignore_file")
            .map(|v| v.map(PathBuf::from).collect())
            .unwrap_or_default(),
        size_constraints,
        time_constraints,
        owner_constraint,
        show_filesystem_errors: matches.get_flag("show_errors"),
        path_separator,
        actual_path_separator,
        max_results,
        strip_cwd_prefix,
        hyperlink,
    })
}

fn check_path_separator_length(path_separator: &Option<String>) -> Result<(), String> {
    match path_separator {
        Some(sep) if cfg!(windows) && sep.len() > 1 => Err(format!(
            "A path separator must be exactly one byte, but the given separator is {} bytes: '{}'.",
            sep.len(),
            sep
        )),
        _ => Ok(()),
    }
}

/// Collect the commands given with -x / -X (or the implicit `ls` for -l).
fn extract_command(
    cmd: &mut clap::Command,
    matches: &ArgMatches,
    colored_output: bool,
) -> Result<Option<CommandSet>, String> {
    if let Some(occurrences) = matches.get_occurrences::<String>("exec") {
        let commands: Vec<Vec<String>> = occurrences.map(|o| o.cloned().collect()).collect();
        return Ok(Some(CommandSet::new(commands)));
    }

    if let Some(occurrences) = matches.get_occurrences::<String>("exec_batch") {
        let commands: Vec<Vec<String>> = occurrences.map(|o| o.cloned().collect()).collect();
        return match CommandSet::new_batch(commands) {
            Ok(set) => Ok(Some(set)),
            Err(e) => {
                let mut plain = cli::build_command();
                let _ = cmd;
                plain.error(ErrorKind::InvalidValue, e.to_string()).exit();
            }
        };
    }

    if matches.get_flag("list_details") {
        let color_arg = format!("--color={}", if colored_output { "always" } else { "never" });
        let ls_cmd: Vec<String> = ["ls", "-l", "-h", "-d", color_arg.as_str()]
            .iter()
            .map(|s| s.to_string())
            .collect();
        return Ok(Some(
            CommandSet::new_batch([ls_cmd]).expect("ls command is a valid batch command"),
        ));
    }

    Ok(None)
}
