        && (matches.get_flag("case_sensitive")
            || pattern_regexps
                .iter()
                .any(|pat| pattern_has_uppercase_char(pat)));

    let path_separator: Option<String> = matches
        .get_one::<String>("path_separator")
        .cloned()
        .or_else(filesystem::default_path_separator);
    let actual_path_separator = path_separator
        .clone()
        .unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
    check_path_separator_length(&path_separator)?;

    let unrestricted = matches.get_count("unrestricted") > 0;
    let hidden = matches.get_flag("hidden") || unrestricted;
    let no_ignore = matches.get_flag("no_ignore") || unrestricted;
    let no_ignore_vcs = matches.get_flag("no_ignore_vcs");

    let interactive_terminal = is_terminal(libc::STDOUT_FILENO);
    let colored_output = match matches
        .get_one::<String>("color")
        .map(|s| s.as_str())
        .unwrap_or("auto")
    {
        "always" => true,
        "never" => false,
        _ => {
            let no_color = env::var_os("NO_COLOR").map_or(false, |v| !v.is_empty());
            !no_color && interactive_terminal
        }
    };

    let hyperlink = match matches
        .get_one::<String>("hyperlink")
        .map(|s| s.as_str())
        .unwrap_or("never")
    {
        "always" => true,
        "never" => false,
        _ => colored_output,
    };

    let ls_colors = if colored_output {
        Some(LsColors::from_env().unwrap_or_else(LsColors::default_theme))
    } else {
        None
    };

    let command = extract_command(cmd, matches, colored_output)?;
    let has_command = command.is_some();

    let threads: usize = matches
        .get_one::<NonZeroUsize>("threads")
        .copied()
        .unwrap_or_else(default_num_threads)
        .get();

    let exact_depth = matches.get_one::<usize>("exact_depth").copied();
    let max_depth = matches.get_one::<usize>("max_depth").copied().or(exact_depth);
    let min_depth = matches.get_one::<usize>("min_depth").copied().or(exact_depth);

    let file_types = matches.get_many::<String>("filetype").map(|values| {
        let mut file_types = FileTypes::default();
        for value in values {
            match value.as_str() {
                "file" => file_types.files = true,
                "directory" => file_types.directories = true,
                "symlink" => file_types.symlinks = true,
                "block-device" => file_types.block_devices = true,
                "char-device" => file_types.char_devices = true,
                "executable" => {
                    file_types.executables_only = true;
                    file_types.files = true;
                }
                "empty" => file_types.empty_only = true,
                "socket" => file_types.sockets = true,
                "pipe" => file_types.pipes = true,
                _ => {}
            }
        }

        // If only 'empty' was specified, search for both files and directories:
        if file_types.empty_only && !(file_types.files || file_types.directories) {
            file_types.files = true;
            file_types.directories = true;
        }

        file_types
    });

    let extensions = matches.get_many::<String>("extension").map(|exts| {
        let patterns = exts
            .map(|e| e.trim_start_matches('.'))
            .map(|e| format!(r".+\.{}$", regex::escape(e)));
        RegexSetBuilder::new(patterns)
            .case_insensitive(true)
            .build()
            .expect("extension regex set")
    });

    let now = SystemTime::now();
    let mut time_constraints: Vec<TimeFilter> = Vec::new();
    if let Some(t) = matches.get_one::<String>("changed_within") {
        if let Some(f) = TimeFilter::after(&now, t) {
            time_constraints.push(f);
        } else {
            return Err(format!(
                "'{}' is not a valid date or duration. See 'fd --help'.",
                t
            ));
        }
    }
    if let Some(t) = matches.get_one::<String>("changed_before") {
        if let Some(f) = TimeFilter::before(&now, t) {
            time_constraints.push(f);
        } else {
            return Err(format!(
                "'{}' is not a valid date or duration. See 'fd --help'.",
                t
            ));
        }
    }

    let size_constraints: Vec<SizeFilter> = matches
        .get_many::<SizeFilter>("size")
        .map(|v| v.copied().collect())
        .unwrap_or_default();

    let owner_constraint: Option<OwnerFilter> = matches
        .get_one::<OwnerFilter>("owner")
        .copied()
        .and_then(OwnerFilter::filter_ignore);

    let null_separator = matches.get_flag("print0");
    let quiet = matches.get_flag("quiet");

    let max_results = if matches.get_flag("max_one_result") {
        Some(1)
    } else {
        matches
            .get_one::<usize>("max_results")
            .copied()
            .filter(|&m| m > 0)
    };

    let has_search_paths = matches.contains_id("path") || matches.contains_id("search_path");
    let strip_cwd_prefix = !has_search_paths
        && match matches
            .get_one::<String>("strip_cwd_prefix")
            .map(|s| s.as_str())
        {
            Some("always") => true,
            Some("never") => false,
            _ => !(null_separator || has_command),
        };

    let format = matches
        .get_one::<String>("format")
        .map(|f| FormatTemplate::parse(f));

    Ok(Config {
        case_sensitive,
        search_full_path: matches.get_flag("full_path"),
        ignore_hidden: !hidden,
        read_fdignore: !no_ignore,
        read_vcsignore: !no_ignore && !no_ignore_vcs,
        require_git_to_read_vcsignore: !matches.get_flag("no_require_git"),
        read_global_ignore: !no_ignore,
        read_parent_ignore: !matches.get_flag("no_ignore_parent"),
        follow_links: matches.get_flag("follow"),
        one_file_system: matches.get_flag("one_file_system"),
        null_separator,
        quiet,
        max_depth,
        min_depth,
        prune: matches.get_flag("prune"),
        threads,
        max_buffer_time: None,
        ls_colors,
        interactive_terminal,
        file_types,
        extensions,
        format,
        command: command.map(Arc::new),
        batch_size: matches.get_one::<usize>("batch_size").copied().unwrap_or(0),
        exclude_patterns: matches
            .get_many::<String>("exclude")
            .map(|v| v.map(|p| format!("!{}", p)).collect())
            .unwrap_or_default(),
        ignore_contain: matches
            .get_many::<String>("ignore_contain")
            .map(|v| v.map(PathBuf::from).collect())
            .unwrap_or_default(),
        ignore_files: matches
            .get_many::<String>("ignore_file")
            .map(|v| v.map(PathBuf::from).collect())
            .unwrap_or_default(),
        size_constraints,
        time_constraints,
        owner_constraint,
        show_filesystem_errors: matches.get_flag("show_errors"),
        path_separator,
        actual_path_separator,
        max_results,
        strip_cwd_prefix,
        hyperlink,
    })
}

fn check_path_separator_length(path_separator: &Option<String>) -> Result<(), String> {
    match path_separator {
        Some(sep) if cfg!(windows) && sep.len() > 1 => Err(format!(
            "A path separator must be exactly one byte, but the given separator is {} bytes: '{}'.",
            sep.len(),
            sep
        )),
        _ => Ok(()),
    }
}

/// Collect the commands given with -x / -X (or the implicit `ls` for -l).
fn extract_command(
    cmd: &mut clap::Command,
    matches: &ArgMatches,
    colored_output: bool,
) -> Result<Option<CommandSet>, String> {
    if let Some(occurrences) = matches.get_occurrences::<String>("exec") {
        let commands: Vec<Vec<String>> = occurrences.map(|o| o.cloned().collect()).collect();
        return Ok(Some(CommandSet::new(commands)));
    }

    if let Some(occurrences) = matches.get_occurrences::<String>("exec_batch") {
        let commands: Vec<Vec<String>> = occurrences.map(|o| o.cloned().collect()).collect();
        return match CommandSet::new_batch(commands) {
            Ok(set) => Ok(Some(set)),
            Err(e) => {
                let mut plain = cli::build_command();
                let _ = cmd;
                plain.error(ErrorKind::InvalidValue, e.to_string()).exit();
            }
        };
    }

    if matches.get_flag("list_details") {
        let color_arg = format!("--color={}", if colored_output { "always" } else { "never" });
        let ls_cmd: Vec<String> = ["ls", "-l", "-h", "-d", color_arg.as_str()]
            .iter()
            .map(|s| s.to_string())
            .collect();
        return Ok(Some(
            CommandSet::new_batch([ls_cmd]).expect("ls command is a valid batch command"),
        ));
    }

    Ok(None)
}
