/// Options that take an optional value are completed without a value specification in zsh.
fn strip_optional_value_specs(buf: Vec<u8>) -> Vec<u8> {
    let Ok(text) = String::from_utf8(buf) else {
        return Vec::new();
    };
    let mut out = String::with_capacity(text.len());
    let mut rest = text.as_str();
    while let Some(idx) = rest.find("]::") {
        out.push_str(&rest[..idx + 1]);
        let after = &rest[idx + 1..];
        match after.find("' \\\\\\n") {
            Some(end) => rest = &after[end..],
            None => rest = after,
        }
    }
    out.push_str(rest);
